/* From Uiverse.io by Yaya12085 - Tags: notification */
.__UIV_SCOPE__ .notification {
  width: 300px;
  height: 70px;
  background: #fff;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #212121;
  box-shadow: 0px 42px 53px 13px rgba(0,0,0,0.1);
  padding: 2px;
  position: relative;
  animation: appear .6s linear alternate-reverse infinite;
  transition: all .6s ease;
}

.__UIV_SCOPE__ .icon {
  height: 100%;
  transition: transform .6s ease;
}

.__UIV_SCOPE__ .messages {
  height: 100%;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  padding: 4px;
}

.__UIV_SCOPE__ .title {
  font-size: 0.95rem;
  line-height: 1rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: #494949;
}

.__UIV_SCOPE__ .description {
  font-size: 13px;
  margin-bottom: 4px;
}

.__UIV_SCOPE__ .level {
  color: #7d5cf5;
  font-weight: 600;
  background-color: #7d5cf53f;
  display: flex;
  align-items: center;
  flex: 1;
  height: 0;
  width: max-content;
  padding: 4px;
  border-radius: 10px;
}

.__UIV_SCOPE__ .level svg {
  height: 140%;
  background-color: #7d5cf5;
  border-radius: 6px;
  margin-right: 4px;
}

.__UIV_SCOPE__ .action {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .action button {
  padding: 0.5rem  1rem;
  background-color: #7d5cf5;
  color: #ffffff;
  font-size: 0.75rem;
  line-height: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  border-radius: 10px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  border: none;
  height: 40px;
  transition: all .6s ease;
  margin-right: 6px;
}

.__UIV_SCOPE__ .notification:hover .icon {
  transform: rotate(45deg);
}

.__UIV_SCOPE__ .action button:hover {
  height: 100%;
  margin-right: 0;
}

.__UIV_SCOPE__ .action button:active {
  background-color: #4dec48;
}

@keyframes appear {
  from {
    transform: scale(0.98);
  }

  to {
    transform: scale(1);
  }
}
